$$
\Mor_{\textit{Ab}(\mathcal{C})}
((\mathcal{F}_1, +, 0, i), (\mathcal{F}_2, +, 0, i))
=
\left\{
\begin{matrix}
\varphi \in \Mor_{\Sh(\mathcal{C})}
(\mathcal{F}_1, \mathcal{F}_2) \\
\varphi \text{ is compatible with }+, 0, i
\end{matrix}
\right\}
$$

